#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);

    size_t pos = s.find("at");
    if (pos != std::string::npos) {
        s.replace(pos, 2, "@");
    }

    if (!s.empty() && s[0] == '@') {
        s = "at" + s.substr(1);
        size_t pos2 = s.find("at", 1);
        if (pos2 != std::string::npos) {
            s.replace(pos2, 2, "@");
        }
    }

    size_t dot_pos;
    while ((dot_pos = s.find("dot")) != std::string::npos) {
        s.replace(dot_pos, 3, ".");
    }

    if (!s.empty() && s[0] == '.') {
        s.replace(0, 1, "dot");
    }

    if (!s.empty() && s.back() == '.') {
        s.replace(s.size() - 1, 1, "dot");
    }

    std::cout << s << std::endl;
    return 0;
}

